PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL; PRAGMA busy_timeout=10000;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS state_capsules(id TEXT PRIMARY KEY,file_path TEXT NOT NULL,exported_at TEXT NOT NULL,imported_at TEXT NOT NULL,state_json BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS capsule_catalogs(capsule_id TEXT NOT NULL REFERENCES state_capsules(id) ON DELETE CASCADE,source_id TEXT NOT NULL,file_path TEXT NOT NULL,sha256 TEXT NOT NULL,size INTEGER NOT NULL,PRIMARY KEY(capsule_id,source_id));
CREATE TABLE IF NOT EXISTS download_epochs(id TEXT PRIMARY KEY,capsule_id TEXT NOT NULL REFERENCES state_capsules(id),source_id TEXT NOT NULL,base_cursor_kind TEXT NOT NULL,base_cursor_value TEXT NOT NULL,target_cursor_kind TEXT NOT NULL,target_cursor_value TEXT NOT NULL,status TEXT NOT NULL,total_bytes INTEGER NOT NULL DEFAULT 0,total_objects INTEGER NOT NULL DEFAULT 0,total_batches INTEGER NOT NULL DEFAULT 0,publish_unit_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,error_text TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS planned_publish_units(id TEXT PRIMARY KEY,epoch_id TEXT NOT NULL REFERENCES download_epochs(id) ON DELETE CASCADE,source_id TEXT NOT NULL,unit_key TEXT NOT NULL,required_count INTEGER NOT NULL DEFAULT 0,metadata_path TEXT NOT NULL DEFAULT '',UNIQUE(epoch_id,unit_key));
CREATE TABLE IF NOT EXISTS planned_artifacts(ordinal INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,epoch_id TEXT NOT NULL REFERENCES download_epochs(id) ON DELETE CASCADE,source_id TEXT NOT NULL,logical_path TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL DEFAULT '',upstream_url TEXT NOT NULL DEFAULT '',upstream_integrity TEXT NOT NULL DEFAULT '',local_source_path TEXT NOT NULL DEFAULT '',operation TEXT NOT NULL,publish_unit_id TEXT NOT NULL,package_key TEXT NOT NULL DEFAULT '',version TEXT NOT NULL DEFAULT '',metadata INTEGER NOT NULL CHECK(metadata IN(0,1)),attributes BLOB,batch_id TEXT NOT NULL DEFAULT '',pack_id TEXT NOT NULL DEFAULT '',pack_offset INTEGER,record_length INTEGER);
CREATE INDEX IF NOT EXISTS ix_planned_unassigned ON planned_artifacts(epoch_id,batch_id,ordinal); CREATE INDEX IF NOT EXISTS ix_planned_pack ON planned_artifacts(pack_id,ordinal);
CREATE TABLE IF NOT EXISTS download_batches(id TEXT PRIMARY KEY,epoch_id TEXT NOT NULL REFERENCES download_epochs(id) ON DELETE CASCADE,source_id TEXT NOT NULL,sequence INTEGER NOT NULL,status TEXT NOT NULL,planned_bytes INTEGER NOT NULL,object_count INTEGER NOT NULL,pack_count INTEGER NOT NULL,output_path TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,UNIQUE(epoch_id,sequence));
CREATE TABLE IF NOT EXISTS download_packs(id TEXT PRIMARY KEY,epoch_id TEXT NOT NULL,batch_id TEXT NOT NULL REFERENCES download_batches(id) ON DELETE CASCADE,sequence INTEGER NOT NULL,size INTEGER NOT NULL DEFAULT 0,sha256 TEXT NOT NULL DEFAULT '',entry_count INTEGER NOT NULL DEFAULT 0,file_path TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,UNIQUE(batch_id,sequence));
CREATE TABLE IF NOT EXISTS download_entries(artifact_id TEXT PRIMARY KEY REFERENCES planned_artifacts(id) ON DELETE CASCADE,batch_id TEXT NOT NULL,pack_id TEXT NOT NULL,status TEXT NOT NULL,downloaded INTEGER NOT NULL DEFAULT 0,etag TEXT NOT NULL DEFAULT '',last_modified TEXT NOT NULL DEFAULT '',error_text TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS download_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,artifact_id TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,error_text TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS workset_keys(namespace TEXT NOT NULL,key TEXT NOT NULL,value TEXT NOT NULL DEFAULT '',PRIMARY KEY(namespace,key)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS client_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
